//! Label: a caption for a form control. Use `r#for` to point it at the control's `id`.
//!
//! Installed by oniko-cn. This file is yours: edit it freely.

use dioxus::prelude::*;
use oniko_cn::{cn, take_class};

const LABEL_BASE: &str = "gap-2 font-semibold peer-data-[slot=checkbox]:text-sm peer-data-[slot=radio-group-item]:text-sm peer-data-[slot=switch]:text-sm leading-relaxed group-data-[disabled=true]:opacity-50 peer-disabled:opacity-50 peer-data-[slot=checkbox]:font-normal peer-data-[slot=radio-group-item]:font-normal peer-data-[slot=switch]:font-normal uppercase text-xs tracking-wide peer-data-[slot=checkbox]:normal-case peer-data-[slot=checkbox]:tracking-normal peer-data-[slot=radio-group-item]:normal-case peer-data-[slot=radio-group-item]:tracking-normal peer-data-[slot=switch]:normal-case peer-data-[slot=switch]:tracking-normal flex items-center select-none group-data-[disabled=true]:pointer-events-none";

/// Label classes for any element, e.g. a styled caption outside of [`Label`].
pub fn label_variants(class: Option<&str>) -> String {
    cn!(LABEL_BASE, class)
}

#[component]
pub fn Label(
    #[props(extends = GlobalAttributes, extends = label)] attributes: Vec<Attribute>,
    children: Element,
) -> Element {
    let mut attributes = attributes;
    let class = label_variants(take_class(&mut attributes).as_deref());

    rsx! {
        label {
            "data-slot": "label",
            class: class,
            ..attributes,
            {children}
        }
    }
}
